INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/1] การเจริญเติบโตและพัฒนาการของร่างกายตามวัย', 'easy', 'mcq', 'เครื่องมือใดใช้สำหรับประเมินการเจริญเติบโตทางร่างกายของนักเรียนว่าสมวัยหรือไม่?', '["เครื่องวัดความดันโลหิต","เครื่องชั่งน้ำหนักและที่วัดส่วนสูง","เทอร์โมมิเตอร์วัดไข้","สายวัดรอบอก"]'::jsonb, 1, 'การชั่งน้ำหนักและวัดส่วนสูงตามเกณฑ์มาตรฐานของกรมอนามัย ใช้ประเมินการเจริญเติบโตของเด็กตามวัย'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] ระบบกล้ามเนื้อ: กล้ามเนื้อลาย', 'medium', 'mcq', 'กล้ามเนื้อชนิดใดที่ยึดติดกับกระดูก ทำงานภายใต้อำนาจจิตใจ (เราสั่งให้ขยับได้ เช่น กล้ามแขน ขา)?', '["กล้ามเนื้อลาย","กล้ามเนื้อเรียบ","กล้ามเนื้อหัวใจ","กล้ามเนื้อกระเพาะอาหาร"]'::jsonb, 0, 'กล้ามเนื้อลาย (Skeletal muscle) ยึดติดกับกระดูกและทำงานภายใต้การควบคุมของจิตใจ เช่น กล้ามเนื้อแขน ขา ลำตัว'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] ระบบกล้ามเนื้อ: กล้ามเนื้อเรียบ', 'medium', 'mcq', 'กล้ามเนื้อที่พบในอวัยวะภายใน เช่น ผนังกระเพาะอาหาร ลำไส้ หลอดเลือด จัดเป็นกล้ามเนื้อชนิดใด?', '["กล้ามเนื้อลาย","กล้ามเนื้อเรียบ","กล้ามเนื้อหัวใจ","กล้ามเนื้อโครงร่าง"]'::jsonb, 1, 'กล้ามเนื้อเรียบ (Smooth muscle) อยู่ตามอวัยวะภายในและทำงานอยู่นอกอำนาจจิตใจโดยอัตโนมัติ'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] กล้ามเนื้อหัวใจ', 'easy', 'mcq', 'กล้ามเนื้อหัวใจมีลักษณะการทำงานอย่างไร?', '["ทำงานเฉพาะตอนที่เราตื่นนอน","ทำงานบีบตัวและคลายตัวตลอดชีวิตอยู่นอกอำนาจจิตใจ","เราสามารถสั่งให้หยุดเต้นได้ตามต้องการ","ทำงานเฉพาะเวลาออกกำลังกาย"]'::jsonb, 1, 'กล้ามเนื้อหัวใจทำงานบีบคลายตัวสูบฉีดเลือดโดยอัตโนมัติตลอดเวลา ไม่สามารถสั่งให้หยุดเต้นได้'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] การดูแลรักษาระบบกล้ามเนื้อ', 'easy', 'mcq', 'สารอาหารประเภทใดจำเป็นที่สุดในการเสริมสร้างและซ่อมแซมกล้ามเนื้อ?', '["คาร์โบไฮเดรต","โปรตีน (เช่น เนื้อสัตว์ ไข่ นม ถั่ว)","ไขมัน","วิตามินซี"]'::jsonb, 1, 'โปรตีนมีกรดอะมิโนที่ช่วยสร้างและซ่อมแซมเส้นใยกล้ามเนื้อที่สึกหรอ'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] ระบบกระดูกและข้อต่อ: หน้าที่ของโครงกระดูก', 'easy', 'mcq', 'หน้าที่สำคัญของโครงกระดูกในร่างกายมนุษย์คือข้อใด?', '["เป็นโครงร่างพยุงร่างกาย ปกป้องอวัยวะภายใน และเป็นที่เกาะของกล้ามเนื้อ","สร้างน้ำย่อยอาหาร","ลำเลียงออกซิเจนในเลือด","ขับเหงื่อระบายความร้อน"]'::jsonb, 0, 'กระดูกช่วยค้ำจุนร่างกาย ป้องกันอวัยวะสำคัญ (เช่น กะโหลกป้องกันสมอง ซี่โครงป้องกันหัวใจและปอด) และช่วยในการเคลื่อนไหว'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] กระดูกซี่โครง', 'easy', 'mcq', 'กระดูกซี่โครงทำหน้าที่สำคัญในการปกป้องอวัยวะภายในใดเป็นหลัก?', '["สมองและตา","หัวใจและปอด","กระเพาะอาหารและลำไส้ใหญ่","ตับและไต"]'::jsonb, 1, 'กรงกระดูกซี่โครงทำหน้าที่เหมือนเกราะป้องกันหัวใจและปอดจากการกระแทกภายนอก'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] แร่ธาตุบำรุงกระดูกและฟัน', 'easy', 'mcq', 'แร่ธาตุชนิดใดมีความสำคัญที่สุดในการเสริมสร้างความแข็งแรงของกระดูกและฟัน?', '["ธาตุเหล็ก","แคลเซียมและฟอสฟอรัส","โซเดียม","ไอโอดีน"]'::jsonb, 1, 'แคลเซียมและฟอสฟอรัส (พบมากในนม ปลาเล็กปลาน้อย ผักใบเขียว) ช่วยให้กระดูกและฟันแข็งแรง'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] การดูแลรักษาข้อต่อและกระดูก', 'medium', 'mcq', 'พฤติกรรมในข้อใดช่วยป้องกันปัญหากระดูกสันหลังคดงอได้ดีที่สุด?', '["นั่งหลังค่อมทำการบ้าน","สะพายกระเป๋าหนักๆ เพียงข้างเดียวตลอดเวลา","นั่งและยืนตัวตรง และสะพายกระเป๋านักเรียนแบบเป้สองสายน้ำหนักพอเหมาะ","นอนคว่ำอ่านหนังสือ"]'::jsonb, 2, 'การจัดบุคลิกภาพนั่งยืนหลังตรง และการกระจายน้ำหนักกระเป๋าเป้สองข้าง ช่วยรักษาสมดุลของแนวกระดูกสันหลัง'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] การอบอุ่นร่างกาย (Warm-up)', 'easy', 'mcq', 'การอบอุ่นร่างกาย (Warm-up) และยืดเหยียดกล้ามเนื้อก่อนเล่นกีฬามีประโยชน์อย่างไร?', '["ช่วยเพิ่มความอบอุ่นของร่างกายและป้องกันการบาดเจ็บของกล้ามเนื้อและข้อต่อ","ทำให้เหนื่อยล้าเร็วกว่าปกติ","ทำให้ไม่ต้องฝึกซ้อมกีฬา","ช่วยให้นอนหลับได้ทันที"]'::jsonb, 0, 'การวอร์มอัพช่วยเพิ่มอุณหภูมิร่างกาย กระตุ้นการไหลเวียนเลือด และเตรียมความพร้อมของกล้ามเนื้อเพื่อลดการบาดเจ็บ'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] ข้อต่อในร่างกาย', 'medium', 'mcq', 'ข้อต่อบริเวณ "หัวไหล่และสะโพก" เป็นข้อต่อชนิดใดที่หมุนได้รอบทิศทาง?', '["ข้อต่อแบบบานพับ","ข้อต่อแบบลูกกลมในเบ้า (Ball and socket)","ข้อต่อแบบเดือย","ข้อต่อที่เคลื่อนไหวไม่ได้"]'::jsonb, 1, 'ข้อต่อแบบลูกกลมในเบ้าที่หัวไหล่และข้อสะโพกช่วยให้แขนและขาสามารถหมุนได้รอบทิศทาง'),
('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/1] วิตามินดีกับกระดูก', 'medium', 'mcq', 'ร่างกายของเราสามารถสร้างวิตามินดีได้เองเมื่อผิวหนังสัมผัสกับสิ่งใดในปริมาณที่เหมาะสมในยามเช้า?', '["สายฝน","แสงแดดอ่อนๆ ยามเช้า","ลมหนาว","ไอหมอก"]'::jsonb, 1, 'แสงแดดยามเช้ามีรังสี UVB ที่ช่วยกระตุ้นให้ผิวหนังสังเคราะห์วิตามินดี ซึ่งช่วยในการดูดซึมแคลเซียมเข้าสู่กระดูก'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/1] คุณลักษณะของครอบครัวที่อบอุ่น', 'easy', 'mcq', 'ข้อใดเป็นลักษณะสำคัญของ "ครอบครัวที่อบอุ่น"?', '["สมาชิกต่างคนต่างอยู่ ไม่พูดคุยกัน","สมาชิกในครอบครัวมีความรัก ความเข้าใจ และพูดคุยปรึกษากันด้วยเหตุผล","พ่อแม่ซื้อของขวัญราคาแพงให้ลูกตลอดเวลาแต่ไม่มีเวลาให้","ใช้อารมณ์และความรุนแรงตัดสินปัญหา"]'::jsonb, 1, 'ครอบครัวที่อบอุ่นเกิดจากความรัก ความเอาใจใส่ การให้เกียรติ และการสื่อสารที่ดีระหว่างกัน'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/1] บทบาทหน้าที่ของลูกในครอบครัว', 'easy', 'mcq', 'นักเรียนสามารถแสดงความกตัญญูและช่วยเหลือครอบครัวได้อย่างไร?', '["ช่วยทำงานบ้านตามกำลังความสามารถ และตั้งใจเรียนหนังสือ","ขอเงินไปเล่นเกมออนไลน์","เกี่ยงงานบ้านกับพี่น้อง","ออกไปเที่ยวนอกบ้านโดยไม่บอกผู้ปกครอง"]'::jsonb, 0, 'การตั้งใจเรียนหนังสือและช่วยเหลืองานบ้านเล็กๆ น้อยๆ เช่น กวาดบ้าน ล้างจาน ช่วยแบ่งเบาภาระของพ่อแม่ได้ดีที่สุด'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/2] การสร้างและรักษาสัมพันธภาพกับเพื่อน', 'easy', 'mcq', 'การปฏิบัติตนข้อใดช่วยให้เป็นที่รักและมีสัมพันธภาพที่ดีกับเพื่อนๆ?', '["ชอบล้อเลียนปมด้อยของเพื่อน","มีน้ำใจ เอื้อเฟื้อเผื่อแผ่ และช่วยเหลือเพื่อนด้วยความจริงใจ","เอาแต่ใจตนเองเป็นหลัก","ยุยงให้เพื่อนทะเลาะกัน"]'::jsonb, 1, 'ความเอื้อเฟื้อ มีน้ำใจ ช่วยเหลือ และรับฟังความคิดเห็นของเพื่อนช่วยสร้างมิตรภาพที่ยั่งยืน'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/2] การแก้ปัญหาความขัดแย้งกับเพื่อน', 'medium', 'mcq', 'เมื่อเกิดความเข้าใจผิดหรือไม่เข้าใจกันกับเพื่อน ควรแก้ไขปัญหาอย่างไร?', '["ใช้กำลังชกต่อยตัดสิน","เปิดใจพูดคุยกันด้วยเหตุผลและรับฟังอีกฝ่ายอย่างใจเย็น","โพสต์ประจานเพื่อนลงบนอินเทอร์เน็ต","เลิกคบเพื่อนทุกคนในห้อง"]'::jsonb, 1, 'การเจรจาด้วยเหตุผลและความใจเย็นเป็นวิธีแก้ปัญหาความขัดแย้งที่ถูกต้องและสร้างสรรค์'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] พฤติกรรมที่เหมาะสมกับเพศสภาพ', 'easy', 'mcq', 'ข้อใดเป็นการปฏิบัติตนที่สุภาพและให้เกียรติซึ่งกันและกันระหว่างเพศ?', '["การใช้คำพูดที่สุภาพ ไม่ล้อเลียนหรือรังแกผู้อื่น","การแตะเนื้อต้องตัวผู้อื่นโดยที่เขาไม่ยินยอม","การดูถูกผู้ที่มีเพศสภาพแตกต่างจากตน","การแย่งชิงสิ่งของของผู้อื่น"]'::jsonb, 0, 'การให้เกียรติซึ่งกันและกัน ไม่ว่าจะเพศใด การใช้คำพูดสุภาพและเคารพสิทธิส่วนบุคคลเป็นสิ่งสำคัญ'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] การป้องกันตนเองจากการล่วงละเมิดทางเพศ', 'medium', 'mcq', 'หากมีคนแปลกหน้ามาขอกอด สัมผัสอวัยวะส่วนตัว หรือชวนไปในที่ลับตาคน ควรทำอย่างไร?', '["ยอมตามใจเพราะเขาให้อมยิ้ม","พูดปฏิเสธเสียงดังว่า \"อย่าทำ!\" แล้วรีบวิ่งหนีไปหาผู้ใหญ่หรือครูทันที","เก็บไว้เป็นความลับคนเดียว","ยืนเฉยๆ ไม่ตอบโต้"]'::jsonb, 1, 'ต้องปฏิเสธอย่างหนักแน่น รีบหนีออกจากสถานการณ์เสี่ยง และแจ้งพ่อแม่หรือคุณครูทันที'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] ร่างกายของเรา สิทธิของเรา (Body Safety)', 'easy', 'mcq', 'ส่วนใดของร่างกายที่ถือเป็น "พื้นที่ส่วนตัว (Private Parts)" ที่ผู้อื่นไม่มีสิทธิ์มาสัมผัสหรือขอดู?', '["มือและแขน","บริเวณที่ปกคลุมด้วยชุดชั้นใน (หน้าอก อวัยวะเพศ และก้น)","เส้นผม","ฝ่าเท้า"]'::jsonb, 1, 'อวัยวะภายใต้ชุดชั้นในเป็นพื้นที่ส่วนตัวที่ห้ามมิให้ใครมาสัมผัสหรือขอดูโดยเด็ดขาด'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/1] ความหลากหลายทางครอบครัว', 'medium', 'mcq', 'ครอบครัวที่ประกอบด้วย ปู่ ย่า พ่อ แม่ ลูก หลาน อาศัยอยู่ร่วมกันในบ้านหลังเดียวกัน เรียกว่าครอบครัวแบบใด?', '["ครอบครัวเดี่ยว","ครอบครัวขยาย","ครอบครัวข้ามรุ่น","ครอบครัวเลี้ยงเดี่ยว"]'::jsonb, 1, 'ครอบครัวขยาย (Extended family) คือครอบครัวที่มีญาติหลายรุ่นอาศัยอยู่ร่วมชายคาเดียวกัน'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/2] การเลือกคบเพื่อน', 'easy', 'mcq', 'การเลือกคบเพื่อนควรพิจารณาจากสิ่งใดเป็นสำคัญ?', '["มีฐานะร่ำรวยและมีของเล่นแพงๆ","มีความประพฤติดี ชักชวนกันเรียนและทำกิจกรรมที่มีประโยชน์","ชอบพากันโดดเรียนไปเล่นเกม","พูดจาหยาบคาย"]'::jsonb, 1, 'เพื่อนที่ดี (กัลยาณมิตร) คือผู้ที่มีความประพฤติดี ชวนกันไปในทางที่สร้างสรรค์และตั้งใจเรียน'),
('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] การเคารพสิทธิความแตกต่างทางเพศ', 'easy', 'mcq', 'ข้อใดเป็นการปฏิบัติตนที่ถูกต้องต่อเพื่อนที่มีอัตลักษณ์ทางเพศหลากหลาย?', '["ตั้งชื่อล้อเลียนเพื่อความสนุกสนาน","ยอมรับ ให้เกียรติ และปฏิบัติต่อเพื่อนทุกคนอย่างเท่าเทียม","กีดกันไม่ให้ร่วมกิจกรรมกลุ่ม","ชักชวนให้คนอื่นรังเกียจ"]'::jsonb, 1, 'ในสังคมประชาธิปไตย เราต้องเคารพและยอมรับความหลากหลายทางเพศของทุกคนอย่างเท่าเทียม'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายแบบอยู่กับที่', 'easy', 'mcq', 'กิจกรรมข้อใดจัดเป็น "การเคลื่อนไหวแบบอยู่กับที่ (Non-locomotor)"?', '["การวิ่งรอบสนาม","การกระโดดกบไปข้างหน้า","การก้มแตะปลายเท้าและบิดลำตัว","การว่ายน้ำข้ามสระ"]'::jsonb, 2, 'การเคลื่อนไหวแบบอยู่กับที่ คือการเคลื่อนไหวร่างกายโดยฐานรองรับน้ำหนักตัวไม่เปลี่ยนจุด เช่น บิดเอว ก้มแตะ ยืนเขย่ง'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายแบบเคลื่อนที่', 'easy', 'mcq', 'ข้อใดเป็น "การเคลื่อนไหวแบบเคลื่อนที่ (Locomotor)"?', '["การยืนกระต่ายขาเดียว","การวิ่งเหยาะๆ และการกระโดดเขย่งไปข้างหน้า","การหมุนคอ","การเหวี่ยงแขน"]'::jsonb, 1, 'การเคลื่อนไหวแบบเคลื่อนที่ คือการทำให้ร่างกายเคลื่อนจากจุดหนึ่งไปยังอีกจุดหนึ่ง เช่น เดิน วิ่ง กระโดด กลิ้ง'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายโดยใช้อุปกรณ์ประกอบ', 'easy', 'mcq', 'กิจกรรมข้อใดเป็นการเคลื่อนไหวร่างกายที่ "ใช้อุปกรณ์ประกอบ (Manipulative)"?', '["การเลี้ยงลูกฟุตบอลและการโยน-รับลูกบอล","การวิ่งแข่ง 50 เมตร","การนอนหงายชันเข่า","การกระโดดตบ"]'::jsonb, 0, 'การใช้อุปกรณ์ประกอบ เช่น ลูกบอล ห่วงฮูลาฮูป เชือกกระโดด ไม้แบดมินตัน'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/2] ทักษะกายบริหารและการยืดหยุ่นขั้นพื้นฐาน', 'medium', 'mcq', 'ท่า "ม้วนหน้า" บนเบาะยางยืดหยุ่น จุดใดของร่างกายควรสัมผัสเบาะเป็นจุดแรกหลังจากมือแตะเบาะ?', '["หน้าผาก","ท้ายทอย (บริเวณคอด้านหลัง)","กลางหลัง","ก้น"]'::jsonb, 1, 'การม้วนหน้าที่ถูกต้องคือก้มคางชิดอก เพื่อให้ "ท้ายทอย" แตะเบาะอย่างปลอดภัย ป้องกันการบาดเจ็บที่คอและหน้าผาก'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/3] เกมเบ็ดเตล็ดและการละเล่นพื้นบ้าน', 'easy', 'mcq', 'การละเล่น "วิ่งเปี้ยว" ช่วยพัฒนาสมรรถภาพทางกายด้านใดมากที่สุด?', '["ความยืดหยุ่นของกล้ามเนื้อ","ความเร็วและความคล่องแคล่วว่องไว","ความอดทนของปอดและหัวใจ","ความแม่นยำ"]'::jsonb, 1, 'วิ่งเปี้ยวเน้นการวิ่งสปีดระยะสั้น การกลับตัว และการรับส่งผ้า จึงช่วยพัฒนาความเร็วและความคล่องตัว'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/4] ทักษะกีฬาแชร์บอลเบื้องต้น', 'medium', 'mcq', 'ในกีฬาแชร์บอล ผู้ถือตะกร้าต้องยืนบนเก้าอี้ มีสิทธิ์ทำสิ่งใดได้?', '["กระโดดลงจากเก้าอี้ไปแย่งบอล","ยืนทรงตัวบนเก้าอี้และขยับตะกร้ารับลูกบอลที่เพื่อนร่วมทีมโยนมา","วิ่งไปรอบๆ สนาม","ผลักผู้เล่นฝ่ายตรงข้าม"]'::jsonb, 1, 'ผู้ถือตะกร้าต้องยืนทรงตัวบนเก้าอี้ ห้ามก้าวเท้าลงมา และสามารถเอียงหรือขยับตะกร้าเพื่อรับลูกบอลได้'),
('สุขศึกษา', 'ป.4', '[พ 3.2 ป.4/1] กฎและกติกาการเล่นกีฬาแฮนด์บอล/แชร์บอล', 'medium', 'mcq', 'ในกีฬาแชร์บอล ผู้เล่นที่ถือลูกบอลสามารถถือลูกบอลไว้ในมือได้ไม่เกินกี่วินาทีโดยไม่ส่งหรือยิง?', '["3 วินาที","5 วินาที","10 วินาที","ไม่จำกัดเวลา"]'::jsonb, 0, 'ตามกติกาแชร์บอลสากล ผู้เล่นสามารถถือลูกบอลไว้ในมือได้ไม่เกิน 3 วินาที'),
('สุขศึกษา', 'ป.4', '[พ 3.2 ป.4/2] น้ำใจนักกีฬา (Sportsmanship)', 'easy', 'mcq', 'ข้อความว่า "รู้แพ้ รู้ชนะ รู้อภัย" มีความหมายตรงกับคุณธรรมข้อใด?', '["ความมีวินัย","ความมีน้ำใจนักกีฬา","ความประหยัด","ความซื่อสัตย์"]'::jsonb, 1, 'น้ำใจนักกีฬาคือการยอมรับความพ่ายแพ้อย่างสง่างาม ชนะอย่างถ่อมตน และให้อภัยเมื่อเกิดอุบัติเหตุในการแข่งขัน'),
('สุขศึกษา', 'ป.4', '[พ 3.2 ป.4/2] การเคารพคำตัดสินของกรรมการ', 'easy', 'mcq', 'เมื่อกรรมการเป่านกหวีดตัดสินว่าลูกออกข้าง แต่เราคิดว่ายังไม่ออก เราควรทำอย่างไร?', '["วิ่งเข้าไปผลักกรรมการ","ยอมรับการตัดสินของกรรมการและเล่นต่อไปตามกติกา","ขว้างลูกบอลทิ้งและไม่ยอมเล่นต่อ","ชวนเพื่อนทั้งทีมเดินออกจากสนาม"]'::jsonb, 1, 'นักกีฬาที่ดีต้องเคารพการตัดสินของผู้ตัดสินและควบคุมอารมณ์ของตนเองตามกติกาการแข่งขัน'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/2] การผ่อนคลายกล้ามเนื้อ (Cool-down)', 'easy', 'mcq', 'หลังจากการออกกำลังกายอย่างหนัก ควรทำสิ่งใดเพื่อปรับอัตราการเต้นของหัวใจให้เข้าสู่ภาวะปกติ?', '["นั่งดื่มน้ำเย็นจัดแก้วใหญ่ทันที","การคลายอุ่นร่างกาย (Cool-down) ด้วยการเดินช้าๆ และยืดกล้ามเนื้อเบาๆ","นอนหลับลงบนพื้นทันที","ไปอาบน้ำเย็นทันที"]'::jsonb, 1, 'Cool-down ช่วยให้เลือดไหลเวียนกลับสู่หัวใจอย่างนุ่มนวลและลดการสะสมของกรดแลกติกในกล้ามเนื้อ'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/3] การแต่งกายที่เหมาะสมกับการเล่นกีฬา', 'easy', 'mcq', 'การแต่งกายไปเล่นกีฬาข้อใดถูกต้องและปลอดภัยที่สุด?', '["สวมกางเกงยีนส์รัดรูปและรองเท้าแตะ","สวมชุดพละที่ระบายอากาศได้ดีและสวมรองเท้าผ้าใบผูกเชือกแน่นหนา","สวมรองเท้าคัทชูหนัง","ใส่เครื่องประดับสร้อยคอทองคำเส้นใหญ่"]'::jsonb, 1, 'ชุดพละและรองเท้าผ้าใบช่วยให้เคลื่อนไหวสะดวกและช่วยดูดซับแรงกระแทก ป้องกันอุบัติเหตุข้อเท้าพลิก'),
('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การทรงตัว (Balance)', 'medium', 'mcq', 'การฝึกเดินบนสันไม้ทรงตัว (Balance beam) ช่วยส่งเสริมสมรรถภาพทางกายด้านใดเป็นหลัก?', '["ความยืดหยุ่น","การทรงตัว (Balance)","พลังกล้ามเนื้อ","ความเร็ว"]'::jsonb, 1, 'การเดินบนสะพานไม้แคบๆ ช่วยฝึกระบบประสาทและการทำงานประสานกันของกล้ามเนื้อเพื่อรักษาสมดุลของร่างกาย'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] อาหารหลัก 5 หมู่: หมู่ที่ 1 โปรตีน', 'easy', 'mcq', 'อาหารในข้อใดจัดอยู่ในอาหารหลักหมู่ที่ 1 (โปรตีน)?', '["ข้าว, แป้ง, เผือก, มัน","เนื้อหมู, ไข่ไก่, นม, ปลา","ผักบุ้ง, แตงกวา, ผักกาดขาว","กล้วยหอม, ส้ม, แตงโม"]'::jsonb, 1, 'อาหารหมู่ที่ 1 ได้แก่ เนื้อสัตว์ นม ไข่ และถั่วเมล็ดแห้ง ให้สารอาหารประเภทโปรตีน'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] อาหารหลักหมู่ที่ 2: คาร์โบไฮเดรต', 'easy', 'mcq', 'สารอาหารประเภทคาร์โบไฮเดรตให้ประโยชน์หลักต่อร่างกายอย่างไร?', '["ให้พลังงานและความอบอุ่นแก่ร่างกายในการทำกิจกรรม","ช่วยรักษาแผลให้หายเร็ว","ช่วยบำรุงสายตา","ช่วยสร้างกระดูกและฟัน"]'::jsonb, 0, 'คาร์โบไฮเดรต (ข้าว แป้ง น้ำตาล เผือก มัน) เป็นแหล่งพลังงานหลักที่ร่างกายนำไปใช้ในการเคลื่อนไหวและทำงาน'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] วิตามินและเกลือแร่ (หมู่ที่ 3 และ 4)', 'easy', 'mcq', 'ผักและผลไม้เป็นแหล่งสำคัญของสารอาหารประเภทใดที่ช่วยให้ระบบขับถ่ายทำงานเป็นปกติ?', '["โปรตีนและไขมัน","วิตามิน แร่ธาตุ และใยอาหาร (Fiber)","คาร์โบไฮเดรตเข้มข้น","คอเลสเตอรอล"]'::jsonb, 1, 'ผักผลไม้อุดมด้วยวิตามิน แร่ธาตุ และกากใยอาหารที่ช่วยกระตุ้นการบีบตัวของลำไส้ ป้องกันอาการท้องผูก'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] วิตามินเอและการบำรุงสายตา', 'medium', 'mcq', 'หากมีอาการมองเห็นไม่ชัดในที่สลัว (โรคตาฟางตอนกลางคืน) ควรรับประทานอาหารที่อุดมด้วยวิตามินใด?', '["วิตามินเอ (เช่น แครอท ฟักทอง ตับ)","วิตามินซี (เช่น ส้ม มะนาว)","วิตามินดี","วิตามินเค"]'::jsonb, 0, 'วิตามินเอช่วยบำรุงสายตาและการมองเห็น พบมากในผักผลไม้สีเหลืองส้มและเครื่องในสัตว์'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] โรคเลือดออกตามไรฟันและวิตามินซี', 'easy', 'mcq', 'การขาดวิตามินซีเป็นเวลานานจะส่งผลให้เกิดโรคใด?', '["โรคเหน็บชา","โรคเลือดออกตามไรฟัน (ลักปิดลักเปิด)","โรคคอพอก","โรคกระดูกอ่อน"]'::jsonb, 1, 'วิตามินซีช่วยให้ผนังหลอดเลือดแข็งแรง หากขาดจะทำให้เกิดเลือดออกตามไรฟันได้ง่าย'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/2] ธงโภชนาการ', 'medium', 'mcq', 'ตามหลัก "ธงโภชนาการ" ของไทย กลุ่มอาหารที่อยู่บริเวณ "ปลายยอดแหลมล่างสุด" คือกลุ่มที่ควรรับประทานน้อยที่สุด ได้แก่อะไร?', '["ข้าวและแป้ง","ผักและผลไม้","น้ำมัน น้ำตาล และเกลือ","นมและเนื้อสัตว์"]'::jsonb, 2, 'ปลายยอดล่างสุดของธงโภชนาการคือน้ำมัน น้ำตาล และเกลือ ซึ่งควรรับประทานในปริมาณน้อยที่สุดเพื่อป้องกันโรคเรื้อรัง'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] การเลือกซื้ออาหารสำเร็จรูปและอาหารกระป๋อง', 'easy', 'mcq', 'ข้อใดเป็นลักษณะของปลากระป๋องที่ "ไม่ควรซื้อ" มารับประทานอย่างเด็ดขาด?', '["มีฉลากและวันหมดอายุระบุชัดเจน","กระป๋องบวม บุบ เป็นสนิม หรือมีรอยรั่วซึม","มีเครื่องหมาย อย. รับรอง","กระป๋องปิดผนึกสนิท"]'::jsonb, 1, 'กระป๋องที่บวมหรือบุบอาจมีการเจริญเติบโตของเชื้อแบคทีเรียคลอสทริเดียม โบทูลินัม ซึ่งสร้างสารพิษอันตรายถึงชีวิต'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] เครื่องหมาย อย.', 'easy', 'mcq', 'เครื่องหมาย อย. รับรองความปลอดภัยของผลิตภัณฑ์อาหารและยา ออกโดยหน่วยงานใด?', '["สำนักงานคณะกรรมการคุ้มครองผู้บริโภค (สคบ.)","สำนักงานคณะกรรมการอาหารและยา กระทรวงสาธารณสุข","กรมการค้าภายใน","กระทรวงศึกษาธิการ"]'::jsonb, 1, 'อย. คือสำนักงานคณะกรรมการอาหารและยา สังกัดกระทรวงสาธารณสุข ตรวจสอบมาตรฐานความปลอดภัยของอาหาร ยา และเครื่องสำอาง'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] การดูวันหมดอายุบนฉลาก (EXP / BBD)', 'easy', 'mcq', 'ข้อความว่า "EXP 15/10/2026" บนกล่องนม หมายความว่าอย่างไร?', '["ผลิตในวันที่ 15 ตุลาคม 2026","หมดอายุในวันที่ 15 ตุลาคม 2026 (ไม่ควรดื่มหลังจากนี้)","ราคา 15 บาท 10 สตางค์","ควรดื่มให้หมดภายใน 15 นาที"]'::jsonb, 1, 'EXP ย่อมาจาก Expiry Date หมายถึง วันที่อาหารหมดอายุ ไม่ควรบริโภคหลังวันดังกล่าว'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/4] สุขภาพจิตและอารมณ์', 'easy', 'mcq', 'เมื่อนักเรียนรู้สึกเครียดจากการเรียนหรือมีเรื่องไม่สบายใจ วิธีปฏิบัติตนข้อใดช่วยคลายเครียดได้อย่างเหมาะสม?', '["ขังตัวเองไว้ในห้องมืดคนเดียว","พูดคุยปรึกษาพ่อแม่ ฟังเพลง หรือออกไปออกกำลังกายกลางแจ้ง","ทุบทำลายข้าวของในบ้าน","อดอาหารประชด"]'::jsonb, 1, 'การพูดคุยกับคนที่ไว้ใจ การฟังเพลง ทำงานอดิเรก หรือเล่นกีฬาช่วยหลั่งสารเอนดอร์ฟินลดความเครียดได้ดี'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] โทษของอาหารขยะ (Junk Food)', 'medium', 'mcq', 'การดื่มน้ำอัดลมและรับประทานขนมกรุบกรอบเป็นประจำทุกวัน จะส่งผลเสียต่อร่างกายอย่างไร?', '["ทำให้กล้ามเนื้อแข็งแรงขึ้น","เสี่ยงต่อการเกิดโรคอ้วน ฟันผุ และได้รับโซเดียมมากเกินไปจนไตทำงานหนัก","ทำให้สายตาดีขึ้น","ช่วยให้กระดูกยาวเร็วขึ้น"]'::jsonb, 1, 'น้ำอัดลมมีน้ำตาลและกรดคาร์บอนิกทำให้ฟันผุ ส่วนขนมกรุบกรอบมีโซเดียมและไขมันอิ่มตัวสูง เสี่ยงต่อโรคอ้วนและโรคไต'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/4] การนอนหลับพักผ่อน', 'easy', 'mcq', 'เด็กในวัยประถมศึกษาตอนปลาย (ป.4) ควรนอนหลับพักผ่อนวันละกี่ชั่วโมงจึงจะเพียงพอต่อการเจริญเติบโต?', '["3-4 ชั่วโมง","5-6 ชั่วโมง","8-10 ชั่วโมง","14-16 ชั่วโมง"]'::jsonb, 2, 'เด็กวัย 9-12 ปี ต้องการการนอนหลับ 8-10 ชั่วโมง เพื่อให้ Growth Hormone หลั่งออกมาช่วยซ่อมแซมร่างกายและเสริมความสูง'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] การดื่มน้ำสะอาด', 'easy', 'mcq', 'ในแต่ละวัน เราควรดื่มน้ำสะอาดอย่างน้อยวันละเท่าใด?', '["1-2 แก้ว","3-4 แก้ว","6-8 แก้ว","15-20 แก้ว"]'::jsonb, 2, 'การดื่มน้ำสะอาดวันละ 6-8 แก้ว ช่วยระบบไหลเวียนโลหิต การขับถ่ายของเสีย และควบคุมอุณหภูมิร่างกาย'),
('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] สารปนเปื้อนในอาหาร: สารบอแรกซ์', 'hard', 'mcq', 'สารเคมีอันตราย "บอแรกซ์" มักถูกลักลอบใส่ในอาหารประเภทใดเพื่อให้เนื้อสัมผัสกรอบเด้ง?', '["ลูกชิ้น, หมูยอ, ทับทิมกรอบ","น้ำส้มคั้น","ข้าวหอมมะลิ","นมสดพาสเจอร์ไรส์"]'::jsonb, 0, 'บอแรกซ์ (น้ำประสานทอง) นิยมลักลอบใส่ในลูกชิ้น หมูยอ ไส้กรอก เพื่อให้กรอบเด้ง เป็นอันตรายต่อไตและระบบทางเดินอาหาร'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/1] การป้องกันอุบัติเหตุในโรงเรียน', 'easy', 'mcq', 'พฤติกรรมใดเสี่ยงต่อการเกิดอุบัติเหตุตกจากที่สูงในโรงเรียน?', '["เดินชิดขวาขึ้นลงบันไดอย่างมีสติ","ปีนป่ายราวระเบียงหรือโหนตัวบนราวบันไดอาคารเรียน","นั่งรับประทานอาหารที่โรงอาหาร","อ่านหนังสือในห้องสมุด"]'::jsonb, 1, 'การปีนป่ายราวระเบียงและโหนราวบันไดเสี่ยงต่อการพลัดตกรุนแรง เกิดการบาดเจ็บที่กระดูกหรือสมองได้'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/1] ความปลอดภัยจากการจราจร', 'easy', 'mcq', 'เมื่อต้องการข้ามถนนในบริเวณที่มีการจราจรหนาแน่น ควรเลือกข้ามที่ใดจึงปลอดภัยที่สุด?', '["วิ่งตัดหน้ารถที่กำลังแล่น","ข้ามบนสะพานลอยคนข้าม หรือทางม้าลายที่มีสัญญาณไฟคนข้าม","มุดใต้ที่กั้นเกาะกลางถนน","ข้ามตรงทางโค้งอับสายตา"]'::jsonb, 1, 'สะพานลอยคนข้ามและทางม้าลายเป็นจุดที่ปลอดภัยที่สุดในการข้ามถนน'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/1] ความปลอดภัยในการโดยสารรถจักรยานยนต์', 'easy', 'mcq', 'อุปกรณ์ความปลอดภัยที่ผู้ขับขี่และผู้ซ้อนท้ายรถจักรยานยนต์ต้องสวมใส่เสมอตามกฎหมายคือข้อใด?', '["หมวกนิรภัย (หมวกกันน็อก)","แว่นตากันแดด","ถุงมือผ้า","เสื้อกันฝน"]'::jsonb, 0, 'หมวกนิรภัยช่วยปกป้องศีรษะและสมองจากการกระแทกเมื่อเกิดอุบัติเหตุทางถนน'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: แผลถลอก', 'medium', 'mcq', 'ขั้นตอนแรกในการปฐมพยาบาลเมื่อมี "แผลถลอก" คือข้อใด?', '["ใช้ผ้าพันแผลพันทับทันที","ล้างแผลด้วยน้ำสะอาดหรือน้ำเกลือล้างแผลและสบู่เพื่อชะล้างสิ่งสกปรก","เอาผงกาแฟมาโรยแผล","ใช้มีดขูดคราบเลือดออก"]'::jsonb, 1, 'ต้องล้างทำความสะอาดแผลด้วยน้ำสะอาดหรือน้ำเกลือเพื่อกำจัดเชื้อโรคและเศษดินก่อนใส่ยาฆ่าเชื้อ'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: เลือดกำเดาไหล', 'medium', 'mcq', 'เมื่อมีเลือดกำเดาไหล วิธีการปฐมพยาบาลที่ถูกต้องที่สุดคือข้อใด?', '["แหงนหน้าขึ้นฟ้าสูงๆ เพื่อไม่ให้เลือดไหล","ก้มหน้าลงเล็กน้อย ใช้นิ้วบีบปีกจมูกทั้งสองข้าง 5-10 นาที และหายใจทางปาก","สั่งน้ำมูกแรงๆ ออกมาทันที","เอาน้ำร้อนราดศีรษะ"]'::jsonb, 1, 'ควรก้มหน้าลงเล็กน้อย (เพื่อไม่ให้เลือดไหลลงคอและสำลัก) แล้วบีบปีกจมูกกดจุดเลือดออกไว้ 5-10 นาที'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: แมลงสัตว์กัดต่อย (ผึ้ง/ต่อ)', 'medium', 'mcq', 'เมื่อถูกผึ้งต่อย สิ่งแรกที่ควรทำคือข้อใด?', '["ใช้วัตถุปลายทื่อ เช่น ขอบบัตรพลาสติกหรือปากกาค่อยๆ ขูดเอาเหล็กในออก แล้วประคบเย็น","ใช้เล็บมือบีบเค้นเหล็กในแรงๆ","นำโคลนมาพอกแผล","เอาไฟมารนบริเวณที่ถูกต่อย"]'::jsonb, 0, 'ใช้บัตรพลาสติกปาดเอาเหล็กในออก ไม่ควรใช้มือบีบเพราะจะทำให้ถุงพิษแตกซึมเข้าสู่ผิวหนังมากขึ้น แล้วประคบเย็นลดปวด'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: ข้อเท้าแพลง (RICE)', 'hard', 'mcq', 'เมื่อข้อเท้าแพลงในช่วง 24-48 ชั่วโมงแรก ควรใช้สิ่งใดประคบเพื่อลดอาการบวมและอักเสบ?', '["กระเป๋าน้ำร้อน","ผ้าห่อน้ำแข็งหรือแผ่นเจลเย็น (Cold pack)","ยานวดน้ำมันมวยร้อน","ใบตองชุบเหล้าขาว"]'::jsonb, 1, 'ในระยะ 48 ชั่วโมงแรกต้องประคบเย็น (Ice) เพื่อให้หลอดเลือดหดตัวลดอาการบวม ห้ามประคบร้อนเด็ดขาด'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] โทษของบุหรี่', 'easy', 'mcq', 'สารเสพติดที่เป็นอันตรายในควันบุหรี่ ซึ่งทำให้เกิดการเสพติดและโรคหัวใจคือสารใด?', '["นิโคตินและทาร์ (น้ำมันดิน)","วิตามินบี","เกลือแร่","ออกซิเจนบริสุทธิ์"]'::jsonb, 0, 'นิโคตินทำให้หัวใจเต้นเร็ว ความดันโลหิตสูงและเสพติด ส่วนทาร์เป็นสารก่อมะเร็งปอดและโรคถุงลมโป่งพอง'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] โทษของเครื่องดื่มแอลกอฮอล์ (สุรา)', 'easy', 'mcq', 'การดื่มสุราหรือเครื่องดื่มแอลกอฮอล์ส่งผลเสียโดยตรงต่ออวัยวะภายในใดจนอาจเกิดโรคตับแข็ง?', '["ตับ","ปอด","หัวใจ","กระเพาะปัสสาวะ"]'::jsonb, 0, 'แอลกอฮอล์ถูกทำลายที่ตับ การดื่มต่อเนื่องทำให้ตับอักเสบ ไขมันพอกตับ และกลายเป็นโรคตับแข็งในที่สุด'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] ยาบ้า (แอมเฟตามีน)', 'medium', 'mcq', 'ยาบ้าออกฤทธิ์ต่อระบบประสาทอย่างไร และส่งผลร้ายแรงอย่างไรต่อผู้เสพ?', '["ทำให้รู้สึกสงบสุข","กระตุ้นประสาท ทำให้ประสาทหลอน หวาดระแวง คุ้มคลั่ง และทำร้ายผู้อื่น","ช่วยให้ความจำดีขึ้น","รักษาโรคเบาหวาน"]'::jsonb, 1, 'ยาบ้าออกฤทธิ์กระตุ้นประสาทอย่างรุนแรง ทำให้เกิดภาพหลอน คุ้มคลั่ง ขาดสติ และอาจก่อความรุนแรงในสังคม'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] สารระเหย (กาว ทินเนอร์)', 'medium', 'mcq', 'การสูดดมสารระเหย (เช่น กาว ทินเนอร์) ส่งผลทำลายอวัยวะสำคัญใดอย่างถาวร?', '["เซลล์สมองเสื่อม ความจำเสื่อม กล้ามเนื้อลีบ","ทำให้ฟันขาวขึ้น","ทำให้ผมยาวเร็ว","ช่วยบำรุงสายตา"]'::jsonb, 0, 'สารระเหยมีสารพิษทำลายเซลล์สมองโดยตรง ทำให้สมองฝ่อ ความจำเสื่อม และระบบประสาทพิการถาวร'),
('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] ทักษะการปฏิเสธสารเสพติด', 'easy', 'mcq', 'หากมีเพื่อนชักชวนให้ทดลองสูบบุหรี่หรือยาเสพติด ควรใช้หลักการใดในการปฏิเสธ?', '["ลองเพียงครั้งเดียวเพื่อไม่ให้เพื่อนเสียน้ำใจ","ปฏิเสธอย่างหนักแน่นว่า \"ไม่ ไม่ลองเด็ดขาด\" และรีบเดินเลี่ยงออกไปทันที","ขอเก็บไว้ก่อนแล้วค่อยนำไปแจกคนอื่น","เงียบไม่พูดอะไร"]'::jsonb, 1, 'ต้องปฏิเสธอย่างจริงจัง มั่นคง ชัดเจน และออกจากสถานการณ์เสี่ยงทันทีโดยไม่ต้องลังเล');
